reviewedCSS:
/* Narrow and fallback-font transports wrap whole controls, never their labels. */
@media(max-width:420px){
  .ct-transport>button{flex:1 0 auto;min-inline-size:6rem;min-height:44px;white-space:nowrap;overflow-wrap:normal;word-break:normal}
  .ct-transport>.ct-step-label{flex:0 0 auto;min-inline-size:max-content;white-space:nowrap}
}
